	ctx = drawingContext;
	centerX = width / 2;
	centerY = height / 2;
	cellSize = width / cellCount;
	let count = 30;
	for (let i = 0; i < count; i++) {
		let n = ceil(map(i, 0, count, 3, -1));
		let span = [1, 2, 4, 8]
		movers.push(new MovingSquare(span[n]));
	}
}

function draw() {
	push();
	translate(centerX, centerY);
	scale(0.75);
	translate(-centerX, -centerY);
	background('#000000');
	for (let i of movers) {
		i.run();
	}
	pop();


}

function easeInOutQuad(x) {
	return x < 0.5 ? 2 * x * x : 1 - Math.pow(-2 * x + 2, 2) / 2;
}

/*------------------------------------------------------------------------------------------*/


class MovingSquare {
	constructor(span) {
		this.span = span;
		this.w = cellSize * this.span;
		this.x = (int(random(cellCount / this.span)) * this.w) + (this.w / 2);
		this.y = (int(random(cellCount / this.span)) * this.w) + (this.w / 2);
		this.curX = this.x;
		this.curY = this.y;

		this.timings = [];
		let t = 0;
		for (let i = 0; i < 5; i++) {
			this.timings.push(t);
			t += 6 * this.span;
		}
		this.x1 = this.x;
		this.y1 = this.y;
		this.reset();
		this.clr = random(palette);
	}

	show() {
		noFill();
		stroke('#ffffff');
		strokeWeight(width / 500);
		square(this.curX, this.curY, this.w);
	}

	update() {
		this.timer++;
		if (this.timings[0] < this.timer && this.timer < this.timings[2]) {
			let nrm = norm(this.timer, this.timings[0], this.timings[2] - 1);
			this.curX = lerp(this.x0, this.x1, easeInOutQuad(nrm));
			this.curY = lerp(this.y0, this.y1, easeInOutQuad(nrm));
		}

		if (this.timer > this.timings[3]) {
			this.reset();
		}
	}

	run() {
		this.show();
		this.update();
	}

	reset() {
		this.x0 = this.x1;
		this.y0 = this.y1;
		do {
			this.coin = [-1, 1];
			this.toggle = [0, 1];
			shuffle(this.coin, true);
			shuffle(this.toggle, true);
			this.x1 = this.x0 + this.w * this.coin[0] * this.toggle[0];
			this.y1 = this.y0 + this.w * this.coin[1] * this.toggle[1];
		} while (
			this.x1 < 0 || this.x1 > width ||
			this.y1 < 0 || this.y1 > height
		)
		this.timer = 0;
	}
}

